from typing import Any

from pydantic import model_validator

from semantic_kernel.connectors.ai.prompt_execution_settings import PromptExecutionSettings
from semantic_kernel.utils.experimental_decorator import experimental_class

# Fields that are recognized by the MistralAI chat completion endpoint and that
# can be copied from a generic ``PromptExecutionSettings`` instance.
_MISTRALAI_SETTINGS_FIELDS = ("temperature", "top_p", "max_tokens", "messages")


@experimental_class
class MistralAIChatPromptExecutionSettings(PromptExecutionSettings):
    """Specific settings for the MistralAI Chat Completion endpoint."""

    temperature: float | None = None
    top_p: float | None = None
    max_tokens: int | None = None
    messages: list[dict[str, Any]] | None = None

    @model_validator(mode="after")
    def check_function_choice_behavior(self) -> "MistralAIChatPromptExecutionSettings":
        """MistralAI does not support function choice behavior."""
        if self.function_choice_behavior is not None:
            raise NotImplementedError(
                "MistralAI does not support function choice behavior, please remove it from the settings."
            )
        return self

    @classmethod
    def from_prompt_execution_settings(
        cls, config: "PromptExecutionSettings"
    ) -> "MistralAIChatPromptExecutionSettings":
        """Create a MistralAI settings object from a generic prompt execution settings object.

        Only the ``service_id`` and the fields recognized by MistralAI are copied over,
        the recognized fields are read from the ``extension_data`` of the source config.
        """
        config.pack_extension_data()
        settings = cls(service_id=config.service_id)
        for field in _MISTRALAI_SETTINGS_FIELDS:
            if field in config.extension_data:
                setattr(settings, field, config.extension_data[field])
        return settings

    def update_from_prompt_execution_settings(self, config: "PromptExecutionSettings") -> None:
        """Update the current settings from another prompt execution settings object."""
        if config.service_id is not None:
            self.service_id = config.service_id
        config.pack_extension_data()
        for field in _MISTRALAI_SETTINGS_FIELDS:
            if field in config.extension_data:
                setattr(self, field, config.extension_data[field])

    def prepare_settings_dict(self, **kwargs: Any) -> dict[str, Any]:
        """Prepare the settings as a dictionary for sending to the MistralAI service."""
        return {
            "temperature": self.temperature,
            "top_p": self.top_p,
            "max_tokens": self.max_tokens,
        }
